// 反編譯 C 虛擬碼對照範例 (IDA / Ghidra Decompiler View)
__int64 __fastcall check_serial_key(const char *license_input)
{
  int len; // [rsp+4h] [rbp-1Ch]
  int i;   // [rsp+8h] [rbp-18h]

  len = strlen(license_input);
  if ( len != 16 )
    return 0LL; // 授權金鑰長度不符
  for ( i = 0; i < len; ++i )
  {
    if ( (license_input[i] ^ 0x5A) != expected_bytes[i] )
      return 0LL; // 混淆校驗失敗
  }
  return 1LL; // 通過硬體驗證
}

